using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Windows.Forms;
namespace CircuitoStudio {
 public sealed class CableFactorsForm:Form {
  readonly Circuit circuit;readonly string file;List<CableFactorRow> rows;readonly NumericUpDown ambient=new NumericUpDown(),groupCount=new NumericUpDown();readonly ComboBox loaded=new ComboBox(),temperature=new ComboBox(),grouping=new ComboBox(),arrangement=new ComboBox();readonly TextBox detail=new TextBox();readonly Button apply=new Button();bool refreshing;
  public bool Changed {get;private set;}
  CableFactorConditions Conditions {get{return new CableFactorConditions{Arrangement=arrangement.SelectedItem as string??"",AmbientC=(double)ambient.Value,GroupCount=(int)groupCount.Value,LoadedConductors=loaded.SelectedItem is int?(int)loaded.SelectedItem:0};}}
  public CableFactorsForm(Project project,Circuit target,string libraryFile){if(project==null||target==null||!project.Boards.Any(board=>board.Circuits.Contains(target)))throw new InvalidDataException("Selecione um circuito do projeto.");circuit=target;file=libraryFile;rows=File.Exists(file)?CableFactors.Import(file):new List<CableFactorRow>();Text="Condições e fatores dos cabos";ClientSize=new Size(970,650);MinimumSize=new Size(900,580);StartPosition=FormStartPosition.CenterParent;Font=new Font("Segoe UI",10);BackColor=Color.White;ShowInTaskbar=false;
   var heading=new Label{Dock=DockStyle.Top,Height=100,Padding=new Padding(14),Text=target.Id+" · "+target.Name+"\r\n"+(target.Cable.Material==ConductorMaterial.Copper?"Cu":"Al")+" / "+target.Cable.Insulation+"; instalação "+target.Cable.InstallationMethod+"; seção "+target.CableMm2+" mm².\r\nAmpacidade-base: "+(String.IsNullOrWhiteSpace(target.Cable.Reference)?"referência não informada":target.Cable.Reference)+". Selecione fatores da mesma referência e das condições declaradas."};
   var controls=new FlowLayoutPanel{Dock=DockStyle.Top,Height=106,Padding=new Padding(10)};ambient.Minimum=-100;ambient.Maximum=200;ambient.DecimalPlaces=1;ambient.Width=80;groupCount.Minimum=1;groupCount.Maximum=10000;groupCount.Width=80;loaded.DropDownStyle=ComboBoxStyle.DropDownList;loaded.Width=65;loaded.Items.AddRange(target.Phases==PhaseMode.Trifasico?new object[]{3,4}:new object[]{2,3,4});var conditions=target.Cable.FactorsSnapshot==null?new CableFactorConditions{AmbientC=30,GroupCount=1,LoadedConductors=target.Phases==PhaseMode.Trifasico?3:2}:target.Cable.FactorsSnapshot.Conditions;ambient.Value=(decimal)conditions.AmbientC;groupCount.Value=conditions.GroupCount;loaded.SelectedItem=loaded.Items.Contains(conditions.LoadedConductors)?conditions.LoadedConductors:loaded.Items[0];
   foreach(Control item in new Control[]{new Label{Text="Temperatura (°C)",AutoSize=true,Padding=new Padding(0,6,0,0)},ambient,new Label{Text="Circuitos agrupados",AutoSize=true,Padding=new Padding(6,6,0,0)},groupCount,new Label{Text="Condutores carregados",AutoSize=true,Padding=new Padding(6,6,0,0)},loaded})controls.Controls.Add(item);
   AddButton(controls,"Importar CSV",Import);AddButton(controls,"Modelo vazio CSV",Template);
   var choices=new TableLayoutPanel{Dock=DockStyle.Top,Height=154,ColumnCount=2,Padding=new Padding(12)};choices.ColumnStyles.Add(new ColumnStyle(SizeType.Absolute,190));choices.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));temperature.DropDownStyle=grouping.DropDownStyle=arrangement.DropDownStyle=ComboBoxStyle.DropDownList;arrangement.Dock=DockStyle.Fill;temperature.DropDownWidth=grouping.DropDownWidth=850;temperature.Dock=grouping.Dock=DockStyle.Fill;choices.Controls.Add(new Label{Text="Arranjo do agrupamento",AutoSize=true},0,0);choices.Controls.Add(arrangement,1,0);choices.Controls.Add(new Label{Text="Fator de temperatura",AutoSize=true},0,1);choices.Controls.Add(temperature,1,1);choices.Controls.Add(new Label{Text="Fator de agrupamento",AutoSize=true},0,2);choices.Controls.Add(grouping,1,2);
   detail.Dock=DockStyle.Fill;detail.Multiline=true;detail.ReadOnly=true;detail.ScrollBars=ScrollBars.Vertical;detail.BackColor=Color.White;var footer=new FlowLayoutPanel{Dock=DockStyle.Bottom,Height=58,Padding=new Padding(10),FlowDirection=FlowDirection.RightToLeft};apply.Text="Aplicar fatores";apply.AutoSize=true;var cancel=new Button{Text="Cancelar",AutoSize=true,DialogResult=DialogResult.Cancel};var remove=new Button{Text="Remover vínculo",AutoSize=true,Enabled=target.Cable.FactorsSnapshot!=null};footer.Controls.Add(apply);footer.Controls.Add(cancel);footer.Controls.Add(remove);apply.Click+=delegate{try{ApplySelected();DialogResult=DialogResult.OK;}catch(Exception ex){MessageBox.Show(this,ex.Message,"Confira os fatores",MessageBoxButtons.OK,MessageBoxIcon.Warning);}};remove.Click+=delegate{CableFactors.Remove(circuit);Changed=true;DialogResult=DialogResult.OK;};CancelButton=cancel;
   Controls.Add(detail);Controls.Add(choices);Controls.Add(controls);Controls.Add(heading);Controls.Add(footer);ambient.ValueChanged+=delegate{RefreshRows();};groupCount.ValueChanged+=delegate{RefreshRows();};loaded.SelectedIndexChanged+=delegate{RefreshRows();};arrangement.SelectedIndexChanged+=delegate{RefreshRows();};temperature.SelectedIndexChanged+=delegate{RefreshDetail();};grouping.SelectedIndexChanged+=delegate{RefreshDetail();};RefreshArrangements();if(target.Cable.FactorsSnapshot!=null)arrangement.SelectedItem=target.Cable.FactorsSnapshot.Conditions.Arrangement;RefreshRows();Shown+=delegate{detail.Select(0,0);ambient.Focus();};
  }
  void AddButton(FlowLayoutPanel panel,string text,Action action){var button=new Button{Text=text,AutoSize=true};button.Click+=delegate{try{action();}catch(Exception ex){MessageBox.Show(this,ex.Message,"Fatores dos cabos",MessageBoxButtons.OK,MessageBoxIcon.Warning);}};panel.Controls.Add(button);}
  void RefreshArrangements(){string previous=arrangement.SelectedItem as string;refreshing=true;try{var available=rows.Where(row=>row.Kind==CableFactorKind.Grouping&&row.Material==circuit.Cable.Material&&row.Insulation==circuit.Cable.Insulation&&String.Equals(row.Installation.Trim(),circuit.Cable.InstallationMethod.Trim(),StringComparison.OrdinalIgnoreCase)&&String.Equals(row.AmpacityReference.Trim(),circuit.Cable.Reference.Trim(),StringComparison.OrdinalIgnoreCase)).Select(row=>row.Arrangement).Distinct().OrderBy(value=>value).ToArray();arrangement.Items.Clear();arrangement.Items.AddRange(available.Cast<object>().ToArray());if(previous!=null&&arrangement.Items.Contains(previous))arrangement.SelectedItem=previous;else if(available.Length==1)arrangement.SelectedIndex=0;else arrangement.SelectedIndex=-1;}finally{refreshing=false;}}
  void RefreshRows(){if(refreshing)return;refreshing=true;try{var t=temperature.SelectedItem as CableFactorRow;var g=grouping.SelectedItem as CableFactorRow;var ts=CableFactors.Filter(rows,circuit,Conditions,CableFactorKind.Temperature);var gs=CableFactors.Filter(rows,circuit,Conditions,CableFactorKind.Grouping);temperature.DataSource=ts;grouping.DataSource=gs;if(t!=null&&ts.Any(row=>row.Id==t.Id))temperature.SelectedItem=ts.First(row=>row.Id==t.Id);if(g!=null&&gs.Any(row=>row.Id==g.Id))grouping.SelectedItem=gs.First(row=>row.Id==g.Id);}finally{refreshing=false;}RefreshDetail();}
  void RefreshDetail(){if(refreshing)return;var t=temperature.SelectedItem as CableFactorRow;var g=grouping.SelectedItem as CableFactorRow;apply.Enabled=t!=null&&g!=null;detail.Text="Valores atuais: "+CableFactors.Describe(circuit)+"\r\n\r\nTemperatura candidata: "+(t==null?"nenhum fator compatível":t.ToString())+"\r\nAgrupamento candidato: "+(g==null?"nenhum fator compatível":g.ToString())+"\r\n\r\nIz corrigida = Iz da tabela × Ft × Fg × paralelos. Não há interpolação. Fonte, versão, condições e faixa de seção são preservadas no projeto. A tabela é fornecida pelo usuário; sua compatibilidade não constitui homologação normativa. O vínculo pode ser removido preservando os números como dados manuais.";}
  void ApplySelected(){CableFactors.Apply(circuit,Conditions,temperature.SelectedItem as CableFactorRow,grouping.SelectedItem as CableFactorRow);Changed=true;}
  void Import(){using(var dialog=new OpenFileDialog{Filter="Tabela de fatores CSV|*.csv"})if(dialog.ShowDialog(this)==DialogResult.OK){var imported=CableFactors.Import(dialog.FileName);if(rows.Count>0&&MessageBox.Show(this,"Substituir a biblioteca atual pelos fatores importados?","Fatores dos cabos",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return;CableFactors.Export(imported,file);rows=imported;RefreshArrangements();RefreshRows();}}
  void Template(){using(var dialog=new SaveFileDialog{Filter="CSV|*.csv",FileName="modelo-fatores-cabos.csv"})if(dialog.ShowDialog(this)==DialogResult.OK){if(String.Equals(Path.GetFullPath(dialog.FileName),Path.GetFullPath(file),StringComparison.OrdinalIgnoreCase))throw new InvalidDataException("Escolha outro nome para preservar a biblioteca ativa.");CableFactors.Export(new CableFactorRow[0],dialog.FileName);}}
 }
 partial class Studio {
  void ConfigureCableFactors(){if(circuit==null)throw new InvalidOperationException("Selecione um circuito.");using(var form=new CableFactorsForm(project,circuit,Path.Combine(userData,"fatores-cabos.csv"))){if(form.ShowDialog(this)==DialogResult.OK&&form.Changed){Change();tabs.SelectedTab=studyPage;}}}
 }
}
